# ✅ AFTER：抽出 Drivetrain 接口，用组合把动力"注入"进来
from typing import Protocol
class Drivetrain(Protocol):
    def start(self) -> None: ...
class GasEngine:
    def start(self): print("汽油引擎轰鸣")
class ElectricMotor:
    def start(self): print("电机静音启动")
class Car:                              # Car HAS-A Drivetrain（组合），不再假设引擎类型
    def __init__(self, drivetrain: Drivetrain): self.drivetrain = drivetrain
    def start(self): self.drivetrain.start()        # 委托给组件

Car(GasEngine()).start()        # 汽油
Car(ElectricMotor()).start()    # 电动
# 加混动/氢能 = 新写一个 Drivetrain，Car 一行不改（OCP）；这就是 Strategy 模式

class Drivetrain:
